//-----------------------------------------------------------------------------
// 1) purely functional spec of “count the number of true’s in a boolean sequence”
//
//    We use a Seq<bool> in the spec world, so that we can call `.is_empty()`,
//    `.head()`, `.tail()`, and write easy recursive specifications.
//
//    count_true_spec(a) = if a is empty, 0
//                         else (if a.head() {1} else {0})
//                              + count_true_spec(a.tail())
//-----------------------------------------------------------------------------

#[verifier::spec]
fn count_true_spec(a: Seq<bool>) -> nat {
    if a.is_empty() {
        0
    } else {
        (if a.head() { 1 } else { 0 })
        + count_true_spec(a.tail())
    }
}

